// ===== Instagram Carousel Publisher =====
// Config node se settings uthao (IG User ID + long-lived access token)
const cfg = $('Config').first().json;
const IG_ID = cfg.igUserId;
const TOKEN = cfg.accessToken;
const API = cfg.apiBase || 'https://graph.instagram.com/v23.0';

// Jo carousel row aayi hai (Split In Batches, batchSize 1)
const row = $input.first().json;

// Slide URLs ikattha karo: slide_1 ... slide_10
const urls = [];
for (let i = 1; i <= 10; i++) {
  const u = row['slide_' + i];
  if (u && String(u).trim() !== '') urls.push(String(u).trim());
}
if (urls.length < 2) throw new Error('Carousel ke liye kam se kam 2 slides chahiye (mila: ' + urls.length + ')');
if (urls.length > 10) urls.length = 10;

const wait = (ms) => new Promise((r) => setTimeout(r, ms));

// 1) Har slide ka child container banao (is_carousel_item = true)
const childIds = [];
for (const url of urls) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: API + '/' + IG_ID + '/media',
    qs: { image_url: url, is_carousel_item: true, access_token: TOKEN },
    json: true,
  });
  if (!res.id) throw new Error('Child container banane me fail: ' + JSON.stringify(res));
  childIds.push(res.id);
}

// 2) Parent CAROUSEL container banao (caption sirf yahan lagta hai)
const parent = await this.helpers.httpRequest({
  method: 'POST',
  url: API + '/' + IG_ID + '/media',
  qs: {
    media_type: 'CAROUSEL',
    children: childIds.join(','),
    caption: row.caption || '',
    access_token: TOKEN,
  },
  json: true,
});
if (!parent.id) throw new Error('Carousel container banane me fail: ' + JSON.stringify(parent));

// 3) Instagram ko multiple assets validate karne ka time do
await wait(10000);

// 4) Publish karo
const pub = await this.helpers.httpRequest({
  method: 'POST',
  url: API + '/' + IG_ID + '/media_publish',
  qs: { creation_id: parent.id, access_token: TOKEN },
  json: true,
});
if (!pub.id) throw new Error('Publish fail: ' + JSON.stringify(pub));

// 5) Live post ka permalink lo (optional)
let permalink = '';
try {
  const info = await this.helpers.httpRequest({
    method: 'GET',
    url: API + '/' + pub.id,
    qs: { fields: 'permalink', access_token: TOKEN },
    json: true,
  });
  permalink = info.permalink || '';
} catch (e) { /* permalink optional */ }

return [{
  json: {
    id: row.id,
    mediaId: pub.id,
    permalink: permalink,
    slideCount: urls.length,
    publishedAt: new Date().toISOString(),
  },
}];
